  cmd=open(f'/proc/{d}/cmdline','rb').read().replace(b'\0',b' ').decode(errors='replace')
  if 'gen.py' in cmd or 'rcb_client' in cmd or 'python -u' in cmd:
   print(d,cmd)
 except Exception: pass
